pub mod users;use actix_web::{web,HttpResponse};use serde::Serialize;#[derive(Serialize)]struct Health{status:&'static str}pub fn configure(cfg:&mut web::ServiceConfig){cfg.route("/healthz",web::get().to(healthz)).service(web::scope("/api").service(web::resource("/users").route(web::get().to(users::list)).route(web::post().to(users::create))).service(web::resource("/users/{id}").route(web::get().to(users::get)).route(web::put().to(users::update)).route(web::delete().to(users::delete_user)))) ;}async fn healthz()->HttpResponse{HttpResponse::Ok().json(Health{status:"ok"})}